import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { RULES } from "../src/code/rules.ts";

/** docs/rules.md is generated from src/code/rules.ts; a test keeps them in sync. */
export function renderRulesDoc(): string {
  const out = [
    "# Code rules",
    "",
    "<!-- Generated by `bun scripts/rules-doc.ts`. Do not edit by hand. -->",
    "",
    "Injection rules (`*-injection`) grade their severity by where the data comes from:",
    "request data in the same function → **critical**, a parameter of the enclosing function → **high**,",
    "any other non-constant string → the default shown below. Dependency findings use the advisory's",
    "own severity (GitHub reviewed label, else CVSS v3 base score).",
    "",
    "| Rule | Default | CWE | Languages |",
    "|---|---|---|---|",
  ];
  for (const r of RULES.values()) {
    out.push(`| [\`${r.id}\`](#${r.id.replace(/\//g, "")}) | ${r.severity} | ${r.cwe.join(", ")} | ${r.languages.join(", ")} |`);
  }
  for (const r of RULES.values()) {
    out.push("", `### ${r.id}`, "", `**${r.title}** — default severity \`${r.severity}\`, ${r.cwe.join(", ")}.`, "", r.help);
  }
  return out.join("\n") + "\n";
}

if (import.meta.main) {
  writeFileSync(join(import.meta.dir, "..", "docs", "rules.md"), renderRulesDoc());
}
